import { safeProviderHttpError } from './standard_errors.ts'
/** First-party DeepSeek Responses: stateless full history, raw reasoning items and automatic cache.
 * Chat is intentionally not used: compaction/steering can insert tool history not generated by the model.
 * Protocol/limits checked 2026-10-18; see docs/provider-research.md. */
import type { ModelMessage } from '../messages.ts'
import { ModelHTTPError, type ModelRequestParameters, type ModelSettings, type RequestContext, type StreamedResponse } from '../model.ts'
import { OpenAIResponsesModel, type ResponsesOptions } from './openai_responses.ts'

export class DeepSeekModel extends OpenAIResponsesModel {
  override get system(): string { return 'deepseek' }
  protected override get plainReasoning(): boolean { return true }

  constructor(model: string, opts: ResponsesOptions = {}) {
    super(model, { ...opts, baseUrl: opts.baseUrl ?? 'https://api.deepseek.com', codex: false,
      profile: { supports_thinking: true, openai_supports_encrypted_reasoning_content: false } })
  }

  override async requestStream(messages: ModelMessage[], settings: ModelSettings, params: ModelRequestParameters, ctx?: RequestContext): Promise<StreamedResponse> {
    try { return await super.requestStream(messages, settings, params, ctx) }
    catch (error) {
      // Provider error bodies can echo arbitrary API keys (GLM keys have no reliably redactable prefix).
      // Keep the HTTP status for retry/access handling, never keep or log the raw response body.
      if (error instanceof ModelHTTPError) throw safeProviderHttpError(error, this.system, this.model_name)
      throw error
    }
  }

  override body(messages: ModelMessage[], settings: ModelSettings, params: ModelRequestParameters): Record<string, unknown> {
    const body = super.body(messages, settings, { ...params, builtin_tools: [] })
    // No state, cache routing keys, encrypted reasoning or summaries on this protocol.
    for (const key of ['store', 'include', 'prompt_cache_key', 'prompt_cache_retention']) delete body[key]
    const level = params.thinking
    const effort = level === false || level === 'off' || level === 'none' ? 'none'
      : level === 'max' || level === 'ultra' ? 'max' : level === 'minimal' || level === 'low' ? 'low' : 'high'
    body.reasoning = { effort }
    if (effort !== 'none') delete body.temperature
    return body
  }
}
